/* q = question, a = answers, c = correct index, e = explanation, lvl = 1..4 */
const QUESTIONS = [
  /* ---------------- CONFIGURATION & SETUP ---------------- */
  { d:"config", lvl:1, q:"A contractor needs to finish a data cleanup at 9pm, but she's locked out after 6pm. Where do you change the hours she's allowed to log in?", a:["Her profile","Her role","Company Information","Session Settings"], c:0, e:"Login Hours and Login IP Ranges both live on the profile. Roles control record visibility, not login access." },
  { d:"config", lvl:1, q:"Which tool grants a user extra access without ever taking access away?", a:["Profile","Permission set","Role","Sharing rule"], c:1, e:"Permission sets are additive only — they layer on top of a profile and can never remove a permission. This is why Salesforce now recommends minimal profiles plus permission sets." },
  { d:"config", lvl:1, q:"Where do you set the org's default currency, locale, and fiscal year start?", a:["Company Information","User Management Settings","My Domain","Business Hours"], c:0, e:"Company Information in Setup holds org-wide defaults for currency, locale, time zone, and fiscal year, plus your license counts." },
  { d:"config", lvl:1, q:"A new hire says a custom app is missing from her App Launcher. Everyone else on her team sees it. What do you check first?", a:["App visibility on her profile or permission set","The role hierarchy","Org-wide defaults","Her license type"], c:0, e:"App visibility is controlled by profile and permission set. Since her teammates can see it, the difference is almost certainly her assigned profile or a missing permission set." },
  { d:"config", lvl:2, q:"What is the purpose of org-wide defaults?", a:["Set the most restrictive baseline access to records","Grant managers access to their team's records","Define which fields appear on a page layout","Control which apps a user can open"], c:0, e:"OWD sets the floor. Every other sharing tool — role hierarchy, sharing rules, manual sharing, teams — only opens access up from that baseline. Start restrictive, then open selectively." },
  { d:"config", lvl:2, q:"Sales reps can see only their own opportunities. Their manager needs to see all of them. What's the standard way to do this?", a:["Place the manager above the reps in the role hierarchy","Give the manager the Modify All Data permission","Change the OWD to Public Read/Write","Create a public group"], c:0, e:"The role hierarchy grants users access to records owned by people below them. Modify All Data is a sledgehammer that grants access to every record in the org." },
  { d:"config", lvl:2, q:"An employee resigns but owns hundreds of open opportunities and is referenced in an active approval process. What should you do right now?", a:["Freeze the user, then reassign records before deactivating","Deactivate the user immediately","Delete the user","Reset the user's password"], c:0, e:"Freezing blocks login instantly but keeps the license consumed. You can't deactivate a user who's still an approver or referenced in a custom hierarchy field, so freeze first, clean up references, then deactivate to free the license." },
  { d:"config", lvl:2, q:"Which statement about sharing rules is true?", a:["They can only extend access, never restrict it","They override org-wide defaults in both directions","They apply only to custom objects","They replace the role hierarchy"], c:0, e:"Sharing rules are exceptions that open access. If you need to restrict below the OWD, you lower the OWD itself or use restriction rules." },
  { d:"config", lvl:3, q:"You need to grant a set of users access to records, and also route cases to that same set for ownership. What do you build?", a:["A queue, since queues can own records and act as a group","A public group only","A role","A permission set group"], c:0, e:"Queues can own records and be used in sharing rules; public groups can't own records. If ownership matters, you need a queue." },
  { d:"config", lvl:3, q:"Manual sharing on a record is available under which condition?", a:["The OWD for that object is Private or Public Read Only","The OWD is Public Read/Write","The user has the View All Data permission","The object has a master-detail relationship"], c:0, e:"Manual sharing only makes sense when access is restricted. If the OWD is already Public Read/Write, there's nothing left to share." },
  { d:"config", lvl:3, q:"What's the difference between Login IP Ranges on a profile and Trusted IP Ranges under Network Access?", a:["Profile ranges block login outright; trusted ranges only skip identity verification","They're identical, just in two places","Profile ranges apply to the API only","Trusted ranges block login outright"], c:0, e:"A profile Login IP Range is a hard gate — outside it, no login. A Trusted IP Range under Network Access just lets users skip the emailed verification code. Confusing these is a classic exam trap." },
  { d:"config", lvl:3, q:"A team lead should be able to reset passwords and manage users for her department only, without becoming a full admin. What do you configure?", a:["Delegated administration","A permission set with Manage Users","The Modify All Data permission","A new profile cloned from System Administrator"], c:0, e:"Delegated administration scopes user management to specified roles and profiles, which is exactly the least-privilege answer." },
  { d:"config", lvl:3, q:"A field was deleted last month and nobody will admit to it. Where do you look?", a:["Setup Audit Trail","Field History Tracking","Debug logs","The Recycle Bin"], c:0, e:"Setup Audit Trail logs configuration changes with the user and timestamp. It shows the last 6 months in the UI, and you can download 20 years of it." },
  { d:"config", lvl:4, q:"You need a sandbox with a copy of production data and metadata for full regression testing before a major release. Which type?", a:["Full sandbox","Partial Copy sandbox","Developer Pro sandbox","Developer sandbox"], c:0, e:"Full is the only sandbox that copies all production data. It refreshes every 29 days. Partial Copy carries a sample data set and refreshes every 5 days." },
  { d:"config", lvl:4, q:"You've built and tested changes in a sandbox. What's required before you can send a change set to production?", a:["A deployment connection authorizing the sandbox to send to production","A managed package","An unmanaged package","Access to the Metadata API"], c:0, e:"Deployment connections must be enabled on the receiving org. You upload an outbound change set from the sandbox and validate the inbound set in production before deploying." },
  { d:"config", lvl:4, q:"A user with a Salesforce Platform license opens a case record and gets an error. What's the likely cause?", a:["Platform licenses don't include standard CRM objects like Cases and Opportunities","The user's profile is missing the Read permission","Cases are disabled in the org","The user needs a permission set group"], c:0, e:"License type is the outermost boundary. Salesforce Platform licenses cover custom objects, Accounts, Contacts, Reports and Dashboards, but not Opportunities, Cases, Forecasts, or Campaigns." },
  { d:"config", lvl:4, q:"Which is required before you can use Lightning components and single sign-on with a branded login page?", a:["My Domain","A Full sandbox","Experience Cloud","A connected app"], c:0, e:"My Domain gives your org a unique login URL. It's a prerequisite for Lightning components, SSO, and social sign-on, and is now enabled for all orgs." },
  { d:"config", lvl:4, q:"You want to bundle several permission sets for a job function and suppress one risky permission that one of them includes. What do you use?", a:["A permission set group with a muting permission set","A cloned profile","A sharing rule","A permission set license"], c:0, e:"Permission set groups combine permission sets for a persona; a muting permission set within the group turns off specific permissions the group would otherwise grant." },
  { d:"config", lvl:2, q:"Which setting forces users out after a period of inactivity?", a:["Session timeout in Session Settings","Login hours on the profile","Password policies","Network Access"], c:0, e:"Session Settings control timeout length, whether to warn before logout, and clickjack protection. Password policies govern expiration and complexity instead." },
  { d:"config", lvl:1, q:"Where would you go to see how many Salesforce licenses your org has used?", a:["Company Information","Users","Profiles","System Overview only"], c:0, e:"Company Information shows used and available licenses by type. System Overview shows storage and other org limits." },

  /* ---------------- OBJECT MANAGER & APP BUILDER ---------------- */
  { d:"object", lvl:1, q:"Which field type should you use to store a discount rate like 12.5%?", a:["Percent","Number","Currency","Formula"], c:0, e:"Percent handles the display and math correctly. Note that in formulas, a Percent field of 12.5% evaluates as 0.125." },
  { d:"object", lvl:1, q:"A user wants to type over a formula field's value. What do you tell them?", a:["Formula fields are read-only and always calculated","Add Edit permission on their profile","Remove the field from the page layout","Change the field-level security"], c:0, e:"Formula fields are calculated at runtime and can never be edited directly. Change the inputs and the formula recalculates." },
  { d:"object", lvl:1, q:"What determines which page layout a user sees on a record?", a:["Their profile, combined with the record type","Their role","The OWD","Their license"], c:0, e:"Page layout assignment is a grid of profile by record type. Change either one and the user may land on a different layout." },
  { d:"object", lvl:1, q:"Which layout controls the fields shown in the highlights panel and in the mobile app's record header?", a:["Compact layout","Page layout","Search layout","List view"], c:0, e:"Compact layouts drive the highlights panel, mobile record headers, and hover details. Page layouts control the full record detail." },
  { d:"object", lvl:2, q:"You need child records to be deleted automatically when the parent is deleted, and to inherit the parent's sharing. Which relationship?", a:["Master-detail","Lookup","Hierarchical","External lookup"], c:0, e:"Master-detail means the child has no owner of its own — it inherits ownership and sharing from the master, and is deleted with it. Lookup relationships are loosely coupled and optional." },
  { d:"object", lvl:2, q:"You want a field on Account showing the total value of all related custom Payment records. What's required?", a:["A master-detail relationship from Payment to Account","A lookup relationship and a formula field","A flow that sums the values","A cross-object formula"], c:0, e:"Roll-up summary fields require master-detail. With only a lookup, you'd need a record-triggered flow to maintain the total." },
  { d:"object", lvl:2, q:"Two sales teams need different stage values and different layouts on the same Opportunity object. What do you use?", a:["Record types with sales processes","Two custom objects","Separate profiles only","Validation rules"], c:0, e:"Record types let one object serve multiple business processes, controlling available picklist values and driving layout assignment per profile." },
  { d:"object", lvl:2, q:"How many master-detail relationships can a single custom object have?", a:["2","1","3","Unlimited"], c:0, e:"A custom object supports at most two master-detail relationships — which is exactly what makes junction objects for many-to-many possible." },
  { d:"object", lvl:2, q:"You're changing a Text field to a Picklist on an object with 40,000 records. What's the main risk?", a:["Data loss or truncation for values that don't fit the new type","The field becomes read-only","The object locks for 24 hours","Record types are removed"], c:0, e:"Field type conversions can silently lose data. Always test in a sandbox and export the current values first." },
  { d:"object", lvl:3, q:"Each Course can have many Students, and each Student can take many Courses. How do you model this?", a:["A junction object with two master-detail relationships","One lookup relationship","Two lookup relationships on Course","A hierarchical relationship"], c:0, e:"The junction object is the standard many-to-many pattern. The first master-detail defined becomes the primary, which controls the junction record's look and feel and record-level access." },
  { d:"object", lvl:3, q:"You want to place individual fields anywhere on a Lightning record page and show or hide them based on record data, without touching the page layout. What do you use?", a:["Dynamic Forms","Dynamic Actions","Compact layouts","Field-level security"], c:0, e:"Dynamic Forms break the page layout's field section into individually placeable components with their own visibility rules. Dynamic Actions does the same for buttons." },
  { d:"object", lvl:3, q:"A related list should only appear when the Account's Type is Customer. Where do you configure that?", a:["Component visibility filters in Lightning App Builder","Page layout properties","A validation rule","Field-level security"], c:0, e:"Every component on a Lightning page has a Set Component Visibility panel that takes filters on record fields, user fields, device, and permissions." },
  { d:"object", lvl:3, q:"You remove a field from a page layout, but it still shows up in reports and the API. What should you have used instead?", a:["Field-level security","A validation rule","A compact layout","A record type"], c:0, e:"Page layouts are UI-only. Field-level security is enforced everywhere — detail pages, list views, reports, search, and the API. If the data is sensitive, FLS is the answer." },
  { d:"object", lvl:3, q:"Which Lightning page type would you build for a dashboard-style landing screen that isn't tied to any single record?", a:["App Page","Record Page","Home Page","Embedded Page"], c:0, e:"App Pages become their own tab in an app. Home Pages replace the default landing screen and can be assigned by app and profile. Record Pages are always tied to one object." },
  { d:"object", lvl:4, q:"You want to convert an existing lookup relationship to master-detail. What must be true?", a:["Every child record must have a value in the lookup field","The child object must have no validation rules","Both objects must have record types","The lookup must be required on the page layout"], c:0, e:"Master-detail requires a parent, so no orphan children are allowed. Populate every blank lookup first, then convert." },
  { d:"object", lvl:4, q:"Which is a genuine limitation of cross-object formula fields?", a:["They can reference parent records up the hierarchy but not child records","They can't reference any other object","They're limited to two objects","They can only be used on custom objects"], c:0, e:"Formulas can walk up through lookups (up to 10 relationships) but can't aggregate down to children. Summing children needs a roll-up summary or a flow." },
  { d:"object", lvl:4, q:"Which calculation is NOT available on a roll-up summary field?", a:["AVERAGE","COUNT","SUM","MIN"], c:0, e:"Roll-up summaries support COUNT, SUM, MIN, and MAX. For an average, roll up both the sum and the count, then divide in a formula field." },
  { d:"object", lvl:4, q:"You've built a Lightning record page for the Support profile using the Escalated record type. How do you make it apply only there?", a:["Use App, Record Type, and Profile assignment on the page","Set it as the org default","Assign it as the app default","Assign it in the page layout editor"], c:0, e:"Lightning page assignment has three levels: org default, app default, and app plus record type plus profile — the most specific one wins." },
  { d:"object", lvl:4, q:"On the User object, what is the Manager field an example of?", a:["A hierarchical relationship","A master-detail relationship","A junction object","An external lookup"], c:0, e:"Hierarchical relationships exist only on the User object and let a user reference another user without creating a circular reference." },
  { d:"object", lvl:2, q:"Which tool gives you a visual, drag-and-drop view of objects, fields, and relationships across the org?", a:["Schema Builder","Object Manager","Lightning App Builder","Setup Audit Trail"], c:0, e:"Schema Builder both visualizes your data model and lets you create objects and fields directly on the canvas." },

  /* ---------------- SALES & MARKETING ---------------- */
  { d:"sales", lvl:1, q:"When a lead is converted, which records are created?", a:["Account and Contact, with an Opportunity optional","Account and Opportunity only","Contact only","Account, Contact, Opportunity, and Case"], c:0, e:"Conversion always produces an Account and a Contact; the Opportunity can be skipped with the 'Don't create an opportunity' checkbox." },
  { d:"sales", lvl:1, q:"Marketing wants campaign statuses like 'Registered' and 'Attended' for a webinar, but different ones for a trade show. Is that possible?", a:["Yes, member statuses are set per campaign","No, they're global to the org","Only with record types","Only in Marketing Cloud"], c:0, e:"Campaign member statuses are defined on each individual campaign, so every campaign can have its own funnel." },
  { d:"sales", lvl:2, q:"A product isn't available to add to a custom price book. What's the likely cause?", a:["The product has no entry in the standard price book","The product is inactive on the opportunity","The user lacks the Manage Products permission","The custom price book isn't shared"], c:0, e:"Every product needs a standard price book entry first — that's the master list price. Custom price book entries are then derived from it." },
  { d:"sales", lvl:2, q:"Changing an Opportunity's Stage automatically updates which fields?", a:["Probability and Forecast Category","Amount and Close Date","Owner and Account","Type and Lead Source"], c:0, e:"Each stage carries a default probability and forecast category. Users can override the probability afterward if the field is editable." },
  { d:"sales", lvl:2, q:"How many lead assignment rules can be active at one time?", a:["One, containing many rule entries","One per profile","Unlimited","Three"], c:0, e:"Only one assignment rule can be active per object, but it can hold many ordered entries. The first matching entry wins and evaluation stops." },
  { d:"sales", lvl:2, q:"Reps keep forgetting which fields matter at each stage of the sales cycle. What's the lightest-touch fix?", a:["Configure Path with key fields and guidance for success","Add validation rules for every stage","Create a record type per stage","Build a screen flow"], c:0, e:"Path shows stage-specific key fields and free-text guidance right on the record, without blocking anyone." },
  { d:"sales", lvl:3, q:"What's the relationship between Products, Price Books, and Price Book Entries?", a:["A price book entry joins a product to a price book with a specific price","A price book is a field on the product","Products belong to exactly one price book","Price book entries are created only by Data Loader"], c:0, e:"Price book entries are the junction that lets one product carry different prices in different price books — regional, partner, or promotional." },
  { d:"sales", lvl:3, q:"Two reps share credit on a deal and both need quota credit. What do you enable?", a:["Opportunity Splits","Opportunity Teams only","Account Teams","Collaborative Forecasts"], c:0, e:"Revenue splits must total 100% and give each rep quota credit. Overlay splits can total any amount for supporting roles." },
  { d:"sales", lvl:3, q:"Reps are creating duplicate leads for the same person. What do you configure?", a:["A matching rule paired with a duplicate rule","A validation rule on Email","A unique External ID field","Web-to-Lead settings"], c:0, e:"The matching rule defines what 'the same' means; the duplicate rule decides whether to allow with an alert, or block outright, and whether to report on it." },
  { d:"sales", lvl:3, q:"A manager wants to drag opportunities between stages visually. What do you point her to?", a:["The Kanban view on the list view","A dashboard","Path","A joined report"], c:0, e:"Kanban is a display option on any list view. It also surfaces alerts for deals with overdue tasks or no activity." },
  { d:"sales", lvl:4, q:"A custom lead field must land on a custom opportunity field at conversion. What's the requirement?", a:["Map the fields in Lead field mapping, with compatible data types","Give both fields the same name","Use a validation rule","Use an assignment rule"], c:0, e:"Lead custom field mapping is in Object Manager under Lead > Fields & Relationships > Map Lead Fields. Data types must be compatible or the mapping fails." },
  { d:"sales", lvl:4, q:"Leadership wants to know which campaigns touched a closed-won deal, not just the last one. What do you enable?", a:["Campaign Influence","Primary Campaign Source only","Campaign member statuses","Opportunity Splits"], c:0, e:"Campaign Influence credits multiple campaigns per opportunity using an attribution model, rather than only the primary campaign source." },
  { d:"sales", lvl:4, q:"What's the daily limit on leads generated through Web-to-Lead?", a:["500","250","1,000","Unlimited"], c:0, e:"Web-to-Lead caps at 500 leads per day. Beyond that, extras are queued or the default lead creator is notified, depending on your settings." },
  { d:"sales", lvl:2, q:"Which forecast category is typically associated with a Closed Won opportunity?", a:["Closed","Commit","Best Case","Pipeline"], c:0, e:"Forecast categories roll stages into Omitted, Pipeline, Best Case, Commit, and Closed. Each stage maps to one by default, and you can change the mapping." },

  /* ---------------- SERVICE & SUPPORT ---------------- */
  { d:"service", lvl:1, q:"Which objects support assignment rules?", a:["Leads and Cases","Cases and Opportunities","Leads and Accounts","All standard objects"], c:0, e:"Assignment rules exist only for Leads and Cases. For other objects you'd use a record-triggered flow to set the owner." },
  { d:"service", lvl:1, q:"Cases untouched for 4 hours should be escalated to a senior queue. What do you build?", a:["An escalation rule","An assignment rule","An auto-response rule","A validation rule"], c:0, e:"Escalation rules are Case-only. They can reassign ownership, notify people, and are based on age since creation or since the last modification." },
  { d:"service", lvl:2, q:"Customers email support@company.com and cases should be created automatically, including attachments over 25 MB. Which setup?", a:["Email-to-Case with the email service agent behind the firewall","On-Demand Email-to-Case","Web-to-Case","An auto-response rule"], c:0, e:"On-Demand Email-to-Case is simpler but caps attachments at 25 MB. The downloadable agent runs behind your firewall and handles larger files." },
  { d:"service", lvl:2, q:"Support cases must be acknowledged with an automatic email the moment they arrive from the web form. What do you configure?", a:["An auto-response rule","An escalation rule","An email alert in a workflow rule","A macro"], c:0, e:"Auto-response rules fire on Web-to-Case, Email-to-Case, and Self-Service submissions, sending a templated acknowledgment immediately." },
  { d:"service", lvl:2, q:"Support and Billing need different Case Status values. What do you configure?", a:["Support processes tied to record types","Two case queues","Validation rules","Two page layouts"], c:0, e:"Support processes are to Case Status what sales processes are to Opportunity Stage — they scope the picklist per record type." },
  { d:"service", lvl:3, q:"An SLA promises first response within 2 hours during business hours, with a visible countdown. What do you configure?", a:["Entitlement process with milestones","Escalation rules","Case teams","Omni-Channel"], c:0, e:"Entitlements define who's covered; the entitlement process defines the milestones with time triggers and actions, and the countdown appears on the case." },
  { d:"service", lvl:3, q:"Cases should be pushed to the available agent with the lightest workload rather than sitting in a queue. What do you use?", a:["Omni-Channel routing","Case assignment rules","Escalation rules","A queue with email alerts"], c:0, e:"Omni-Channel push-routes work based on agent presence status and capacity, instead of the pull model where agents cherry-pick from a queue." },
  { d:"service", lvl:3, q:"Agents repeat the same five clicks on every case: set status, add a comment, send an email. What's the quickest fix?", a:["A macro","A screen flow","A validation rule","A quick action"], c:0, e:"Macros bundle repetitive console actions into one click. Bulk macros can even run against many records at once." },
  { d:"service", lvl:3, q:"In Knowledge, what controls which articles a given audience can see?", a:["Data categories","Record types","Article layouts","Case teams"], c:0, e:"Data categories organize articles and control visibility by role, permission set, or profile through category group visibility settings." },
  { d:"service", lvl:4, q:"An engineer needs access to one specific case without gaining access to any other case. What's the lightest option?", a:["Add them to the case team","Change the OWD to Public Read/Write","Give them View All on Cases","Add them to the support role"], c:0, e:"Case teams grant per-record access with a defined role, which is far narrower than changing the OWD or granting object-wide permissions." },
  { d:"service", lvl:4, q:"Which app type gives agents a tabbed workspace with subtabs so they can work several cases at once?", a:["A Lightning console app","A standard Lightning app","A Classic app","An Experience Cloud site"], c:0, e:"Console apps use a workspace-and-subtab navigation model built for high-volume work, plus utility bar items like History and Notes." },
  { d:"service", lvl:2, q:"Where do you define the hours used by escalation rules and entitlement milestones?", a:["Business Hours in Setup","Company Information","Session Settings","The user's profile"], c:0, e:"Business Hours, with optional holidays, drive escalation timing and milestone countdowns so weekends don't count against your SLA." },
  { d:"service", lvl:4, q:"Cases from a queue should be owned by a group, but you also want reporting on who actually resolved each one. What do you do?", a:["Route to a queue, then have agents accept ownership","Assign directly to individuals","Use a public group","Use a case team"], c:0, e:"Queues hold unassigned work. When an agent accepts a case, ownership transfers to them, which makes individual resolution reporting straightforward." },
  { d:"service", lvl:1, q:"Which feature creates cases directly from a form on your public website?", a:["Web-to-Case","Email-to-Case","Web-to-Lead","Omni-Channel"], c:0, e:"Web-to-Case generates HTML you embed on a site. It's capped at 5,000 cases per day and works alongside auto-response and assignment rules." },
];

const QUESTIONS2 = [
  /* ---------------- PRODUCTIVITY & COLLABORATION ---------------- */
  { d:"prod", lvl:1, q:"Which Chatter group type is invisible in search and the group list to anyone who isn't a member?", a:["Unlisted","Private","Public","Broadcast"], c:0, e:"Private groups appear in listings but hide their content. Unlisted groups are invisible entirely — only members and users with Modify All Data can find them." },
  { d:"prod", lvl:1, q:"A task should be linked to five contacts from the same meeting. What must be enabled?", a:["Shared Activities","Activity feed tracking","Einstein Activity Capture","Multi-select picklists"], c:0, e:"Shared Activities lets one activity relate to up to 10 contacts plus one other record. Once enabled it can't be turned off, so decide deliberately." },
  { d:"prod", lvl:2, q:"What's the difference between a global action and an object-specific action?", a:["Global actions can be used anywhere; object-specific ones are tied to one object and can prefill from the record","Global actions are Classic only","Object-specific actions can't create records","There is no functional difference"], c:0, e:"Object-specific actions live on that object's page layout and inherit context from the parent record. Global actions appear in the publisher and App Launcher anywhere." },
  { d:"prod", lvl:2, q:"Users want to be notified when an Opportunity's Amount changes, in the record feed. What do you configure?", a:["Feed tracking on the Amount field","A workflow rule","A validation rule","A report subscription"], c:0, e:"Feed tracking posts field changes to the record's Chatter feed. It's limited to 20 tracked fields per object." },
  { d:"prod", lvl:2, q:"Which item did Salesforce replace with Files, offering versioning and sharing across records?", a:["Attachments","Notes and Attachments related list only","Documents tab only","Chatter posts"], c:0, e:"Files (ContentDocument) support versioning, previews, and sharing one file to many records. Legacy Attachments are tied to a single parent." },
  { d:"prod", lvl:3, q:"Emails sent from Salesforce are landing in spam. Which setting should you review first?", a:["Deliverability settings, including SPF, DKIM, and access level","Email templates","Organization-wide email addresses only","Session settings"], c:0, e:"Deliverability controls the access level (No access, System email only, All email) and lets you set up DKIM keys and bounce management." },
  { d:"prod", lvl:3, q:"Sales wants all emails and meetings logged against Salesforce records automatically, without manual entry. What do you look at?", a:["Einstein Activity Capture","Feed tracking","Web-to-Lead","Salesforce Files"], c:0, e:"Einstein Activity Capture syncs email and events from Google or Microsoft. Note that captured activity is stored outside the standard Activity object, which limits reporting on it." },
  { d:"prod", lvl:3, q:"How do you give the Sales profile a different Lightning Home page from the Service profile?", a:["Build two Home pages and use App and Profile assignment","Use record types","Use two page layouts","Use compact layouts"], c:0, e:"Lightning Home pages are assigned by app and profile in Lightning App Builder, so each persona can land on a purpose-built screen." },
  { d:"prod", lvl:2, q:"Which email template type lets you build a reusable template with merge fields and rich formatting in Lightning?", a:["Lightning email template","Visualforce template","Text template only","Letterhead"], c:0, e:"Lightning email templates support rich text, merge fields, and can be shared via folders. Classic templates include Text, HTML with letterhead, Custom, and Visualforce." },
  { d:"prod", lvl:4, q:"Which fields appear on a record in the Salesforce mobile app's header?", a:["The compact layout's fields","The first four page layout fields","The search layout's fields","All required fields"], c:0, e:"Compact layouts drive the mobile header and the desktop highlights panel. The first field becomes the record's title." },
  { d:"prod", lvl:4, q:"An admin wants a quick action available from anywhere in the app, including the App Launcher. Where is it added?", a:["The global publisher layout","Every object's page layout","The compact layout","The search layout"], c:0, e:"Global actions are added to the global publisher layout, which controls the actions available in the Chatter publisher and global header." },
  { d:"prod", lvl:1, q:"What's the difference between a Task and an Event?", a:["Events occupy a time slot on the calendar; tasks are to-dos with a due date","Tasks can't be assigned to others","Events can't be recurring","There is no difference"], c:0, e:"Both are Activities under the hood, which is why they share the Activity History and Open Activities related lists and can be reported on together." },

  /* ---------------- DATA & ANALYTICS ---------------- */
  { d:"data", lvl:1, q:"You need to delete 80,000 obsolete records. Which tool?", a:["Data Loader","Data Import Wizard","Mass Transfer Records","Report export"], c:0, e:"The Data Import Wizard cannot delete at all. Data Loader supports insert, update, upsert, delete, hard delete, export, and export all." },
  { d:"data", lvl:1, q:"How long do deleted records stay recoverable in the Recycle Bin?", a:["15 days","30 days","60 days","Indefinitely"], c:0, e:"15 days, after which records are permanently purged. Hard delete via Data Loader skips the Recycle Bin entirely." },
  { d:"data", lvl:1, q:"Which report format lets you group data by both rows and columns?", a:["Matrix","Summary","Tabular","Joined"], c:0, e:"Tabular is a flat list, summary groups by rows, matrix groups by rows and columns, and joined shows up to five blocks side by side." },
  { d:"data", lvl:2, q:"You're loading 30,000 contacts and want to avoid creating duplicates for records already in Salesforce. Which operation?", a:["Upsert, keyed on an External ID field","Insert","Update","Hard delete"], c:0, e:"Upsert matches on an External ID: it updates when a match exists and inserts when it doesn't, in a single pass." },
  { d:"data", lvl:2, q:"A dashboard shows different numbers to different viewers, matching what each can access. What's configured?", a:["The dashboard runs as the logged-in user","The dashboard runs as a specified user","Dashboard filters","Report folder sharing"], c:0, e:"'Run as logged-in user' is the dynamic dashboard setting, so each viewer sees only their own data. A specified running user shows everyone the same numbers." },
  { d:"data", lvl:2, q:"Users need Opportunity data grouped into 'Small', 'Medium', and 'Large' without creating a new field. What do you use?", a:["A bucket field in the report","A formula field","A custom report type","A cross filter"], c:0, e:"Bucket fields categorize numeric, picklist, or text values inside a single report — no metadata change required." },
  { d:"data", lvl:2, q:"How many fields can you enable for field history tracking on a single object?", a:["20","10","40","Unlimited"], c:0, e:"20 fields per object, with history retained for 18 to 24 months. Field Audit Trail extends retention up to 10 years." },
  { d:"data", lvl:3, q:"You need a report showing Accounts that have no Opportunities. How?", a:["A custom report type with a 'without' relationship, or a cross filter","A summary report grouped by Account","A joined report","A matrix report"], c:0, e:"Custom report types let you say 'A records may or may not have related B records'. Cross filters add 'with' or 'without' logic to a standard report type." },
  { d:"data", lvl:3, q:"A custom report type's primary object can be linked to how many related objects?", a:["3","1","5","Unlimited"], c:0, e:"Up to four objects total: the primary plus three related. Each relationship is set as either 'must have' or 'may or may not have'." },
  { d:"data", lvl:3, q:"How do you calculate what percentage each region contributes to the grand total inside a report?", a:["A custom summary formula using PARENTGROUPVAL","A bucket field","A cross filter","A roll-up summary"], c:0, e:"PARENTGROUPVAL references a higher grouping level; PREVGROUPVAL compares to the previous grouping, which is how you build period-over-period change." },
  { d:"data", lvl:3, q:"You want to capture pipeline totals every Friday to trend them over months. What do you configure?", a:["A reporting snapshot","A scheduled report","A dashboard subscription","A dynamic dashboard"], c:0, e:"Reporting snapshots write report results into a custom object on a schedule, which is the only way to build true historical trending from live data." },
  { d:"data", lvl:3, q:"How do you control who can view, edit, or manage a set of reports?", a:["Report folder sharing with Viewer, Editor, or Manager access","Field-level security","Org-wide defaults","Report types"], c:0, e:"Folder access levels are Viewer, Editor, and Manager. Note this controls the reports themselves — the underlying record access still applies to the data inside." },
  { d:"data", lvl:4, q:"You need a nightly automated export of all org data to your data warehouse team. Which is the standard, no-code option?", a:["Data Export Service on a weekly or monthly schedule","Data Loader command line interface","Report subscriptions","Reporting snapshots"], c:0, e:"The Data Export Service is scheduled weekly or monthly. For a truly nightly export you'd script the Data Loader CLI — which is exactly why the exam contrasts the two." },
  { d:"data", lvl:4, q:"A joined report can contain how many blocks?", a:["5","3","10","2"], c:0, e:"Up to five blocks, each with its own report type, columns, and filters, sharing common groupings down the left." },
  { d:"data", lvl:4, q:"You add a tabular report to a dashboard and get an error. What's required?", a:["Set a row limit and sort on the report","Convert it to a matrix report","Add a grouping","Add a bucket field"], c:0, e:"Tabular reports have no groupings, so a dashboard component needs a row limit and sort order to know what to display." },
  { d:"data", lvl:4, q:"How many filters can a viewer apply to a single Lightning dashboard?", a:["3","1","5","10"], c:0, e:"Up to three dashboard filters, each with up to 50 values. Filters let one dashboard serve many segments instead of building duplicates." },
  { d:"data", lvl:2, q:"Which import tool is limited to 50,000 records and cannot import every object?", a:["Data Import Wizard","Data Loader","Workbench","Bulk API"], c:0, e:"The Import Wizard covers Accounts, Contacts, Leads, Campaign Members, Person Accounts, and custom objects, with built-in duplicate prevention." },
  { d:"data", lvl:3, q:"Records were imported with the wrong owner. What's the fastest way to reassign them in bulk?", a:["Mass Transfer Records in Setup","Edit each record","Data Loader delete and reinsert","A sharing rule"], c:0, e:"Mass Transfer Records reassigns ownership in bulk for supported objects, with the option to also transfer open activities and related records." },
  { d:"data", lvl:4, q:"An admin needs to report on records both a user owns and records shared with them, showing only rows from the last fiscal quarter. Which filter is date-relative?", a:["LAST FISCAL QUARTER as a relative date literal","A formula field","A bucket field","A cross filter"], c:0, e:"Relative date literals like LAST FISCAL QUARTER and THIS MONTH keep reports current without editing filters every period." },
  { d:"data", lvl:1, q:"Which dashboard component would you use to show progress toward a single goal number?", a:["Gauge","Table","Matrix","Funnel"], c:0, e:"A gauge shows one value against defined breakpoints. A metric shows a single number without the dial." },
  { d:"data", lvl:2, q:"How do you let a user see a report but not change it?", a:["Give Viewer access to the report folder","Remove Edit on their profile","Use field-level security","Deactivate the report"], c:0, e:"Viewer access allows running and refreshing. Note that a user with 'Save As' can still create their own copy in a folder they can edit." },
  { d:"data", lvl:3, q:"Duplicate accounts keep appearing despite a duplicate rule. What's the most likely cause?", a:["The matching rule isn't active or its criteria are too narrow","The OWD is too open","Field history tracking is off","The report type is wrong"], c:0, e:"A duplicate rule does nothing without an active matching rule behind it. Check that the matching rule is active and that its fields catch the real-world variations." },

  /* ---------------- AUTOMATION ---------------- */
  { d:"auto", lvl:1, q:"A validation rule's formula evaluates to TRUE. What happens?", a:["The error message displays and the save is blocked","The record saves successfully","The field is cleared","A flow is triggered"], c:0, e:"Validation rules are backwards from intuition: TRUE means the error condition is met, so the save fails. Write the formula to describe what's wrong, not what's right." },
  { d:"auto", lvl:1, q:"Which flow type presents a user interface with pages of inputs?", a:["Screen flow","Record-triggered flow","Scheduled-triggered flow","Platform event-triggered flow"], c:0, e:"Screen flows are the only type with a UI. They can be launched from buttons, quick actions, Lightning pages, or Experience Cloud." },
  { d:"auto", lvl:2, q:"You need to update a field on the same record that fired the trigger, as fast as possible. What's the best option?", a:["A before-save record-triggered flow","An after-save record-triggered flow","A scheduled flow","An approval process"], c:0, e:"Before-save flows update the record in memory before it's written, so there's no second save. They're roughly ten times faster and can't send emails or create other records." },
  { d:"auto", lvl:2, q:"Which two legacy tools has Salesforce retired in favor of Flow?", a:["Workflow Rules and Process Builder","Validation rules and approval processes","Assignment rules and escalation rules","Quick actions and macros"], c:0, e:"Both Workflow Rules and Process Builder are retired for new automation. Migration tools exist in Setup, and the exam now expects Flow-first answers." },
  { d:"auto", lvl:2, q:"A record should be updated 7 days after the close date. In a record-triggered flow, what do you use?", a:["A scheduled path","A pause element in a screen flow","A scheduled-triggered flow","A time-based workflow action"], c:0, e:"Scheduled paths run at a set offset from a date field or from when the record was created or updated — this is the Flow replacement for time-dependent workflow actions." },
  { d:"auto", lvl:2, q:"Discounts over 20% need manager sign-off before the opportunity can proceed. What do you build?", a:["An approval process","A validation rule","A screen flow","An escalation rule"], c:0, e:"Approval processes route records through defined steps with approvers, and can lock the record on submission and take actions on approval or rejection." },
  { d:"auto", lvl:3, q:"In the order of execution, when do before-save record-triggered flows run relative to validation rules?", a:["Before custom validation rules","After all validation rules","After workflow rules","At the same time"], c:0, e:"Order: system validation, then before-save flows, then custom validation rules, then the save, then after-save flows and other automation. So a before-save flow can set a value that then gets validated." },
  { d:"auto", lvl:3, q:"A flow errors out when a Get Records element finds nothing. What should you add?", a:["A decision checking whether the record variable is null, plus a fault path","A loop","A second Get Records","An assignment element"], c:0, e:"Always check for null after a Get Records, and connect fault paths so users see a helpful screen or an admin gets notified instead of a raw error." },
  { d:"auto", lvl:3, q:"You want a flow to run only when Status changes from anything to Closed, not on every edit. How?", a:["Set the entry condition and choose 'Only when a record is updated to meet the condition requirements'","Use a decision element only","Use a scheduled path","Use ISCHANGED in a validation rule"], c:0, e:"That trigger option evaluates the prior values too, so the flow fires on the transition rather than on every subsequent save while the condition stays true." },
  { d:"auto", lvl:3, q:"Which element do you use to process every record returned by a Get Records collection one at a time?", a:["Loop","Decision","Assignment","Subflow"], c:0, e:"Loop iterates over a collection. Best practice is to build a new collection inside the loop and do a single Update Records after the loop, not inside it." },
  { d:"auto", lvl:3, q:"An integration user is being blocked by a validation rule that shouldn't apply to it. What's a clean solution?", a:["Add a custom permission check to the validation rule and grant it via permission set","Deactivate the validation rule","Give the user Modify All Data","Delete the rule"], c:0, e:"Wrapping the rule in $Permission.Bypass_Validation lets you exempt specific users through a permission set, without weakening the rule for everyone." },
  { d:"auto", lvl:4, q:"A nightly process should update all opportunities past their close date. Which flow type?", a:["Scheduled-triggered flow","Record-triggered flow","Screen flow","Autolaunched flow with no trigger"], c:0, e:"Scheduled-triggered flows run at a set time and frequency against a filtered set of records — the declarative replacement for a batch job." },
  { d:"auto", lvl:4, q:"What does an approval process's default initial submission action do?", a:["Locks the record from editing","Sends an email alert","Updates the status field","Creates a task"], c:0, e:"Record lock is the default. Admins and approvers can still be allowed to edit locked records depending on the process settings." },
  { d:"auto", lvl:4, q:"Which function lets a validation rule compare a field against its value before the edit?", a:["PRIORVALUE","ISCHANGED","ISNEW","VLOOKUP"], c:0, e:"PRIORVALUE returns the previous value. ISCHANGED returns true if the field changed at all. Neither works on record creation, so pair them with NOT(ISNEW())." },
  { d:"auto", lvl:4, q:"You want to test a flow's logic against a real record without affecting data. What do you use?", a:["Debug in Flow Builder with rollback mode","A sandbox refresh","The Setup Audit Trail","A validation rule"], c:0, e:"Flow debug lets you step through with a chosen record and shows each element's inputs and outputs. Rollback mode discards any changes it makes." },
  { d:"auto", lvl:4, q:"A flow must create records the running user doesn't have permission to create. What do you configure?", a:["Set the flow to run in System Context Without Sharing","Give every user Modify All Data","Use a before-save flow","Add a fault path"], c:0, e:"Flow run context can be set to system context, which bypasses the running user's object, field, and record permissions. Use it deliberately — it's a real security decision." },
  { d:"auto", lvl:2, q:"What's the simplest way to send a templated email automatically when a case closes?", a:["A record-triggered flow with an email alert action","A macro","An auto-response rule","An assignment rule"], c:0, e:"Email alerts are reusable actions combining a template and recipients, and they can be called from flows and approval processes." },
  { d:"auto", lvl:1, q:"Which formula function returns true only when a record is being created?", a:["ISNEW()","ISCHANGED()","PRIORVALUE()","ISBLANK()"], c:0, e:"ISNEW() is often combined with validation logic so a rule applies only on insert, or is excluded on insert." },
  { d:"auto", lvl:3, q:"Where do you reuse one flow's logic inside another flow?", a:["A subflow element calling an autolaunched flow","A loop element","A decision element","A platform event"], c:0, e:"Subflows keep logic in one place. Only autolaunched flows can be called as subflows from a record-triggered flow." },
  { d:"auto", lvl:1, q:"Which automation blocks a record from saving when data is invalid?", a:["Validation rule","Flow","Approval process","Assignment rule"], c:0, e:"Validation rules are the standard guardrail for data quality, running on save from the UI, the API, and imports alike." },

  /* ---------------- AGENTFORCE ---------------- */
  { d:"agent", lvl:1, q:"In Agent Builder, what is a Topic?", a:["A job to be done, grouping related instructions and actions","A single automated action","A data source","A permission set"], c:0, e:"Topics scope what an agent can handle. Each has a description that helps the agent decide when to use it, plus instructions and a set of allowed actions." },
  { d:"agent", lvl:1, q:"What does the Einstein Trust Layer's zero data retention mean?", a:["Your prompts and responses aren't stored by the third-party model provider","Salesforce doesn't store your records","Conversations are never logged","Data Cloud is bypassed"], c:0, e:"Zero retention is contractual with the LLM providers. Salesforce still keeps its own audit trail and feedback data on your side of the boundary." },
  { d:"agent", lvl:2, q:"An agent is returning records a user shouldn't see. What's the first thing to check?", a:["The permissions of the user the agent runs as","The prompt template wording","The Data Cloud connection","The agent's topic descriptions"], c:0, e:"Agents run as an assigned user and respect that user's object, field, and record-level permissions. Over-broad agent access is almost always an over-permissioned agent user." },
  { d:"agent", lvl:2, q:"Which capability of the Trust Layer removes personally identifiable information before a prompt reaches the model?", a:["Data masking","Toxicity detection","Dynamic grounding","Prompt defense"], c:0, e:"Masking replaces sensitive values with placeholders on the way out and restores them in the response. Toxicity detection scores outputs for harmful content instead." },
  { d:"agent", lvl:2, q:"What are Instructions in a topic?", a:["Natural-language guardrails telling the agent how to behave within that topic","Apex code","A flow definition","Field-level security settings"], c:0, e:"Instructions are plain-language rules — what to always do, never do, and when to hand off to a human. Clear, specific instructions are the main lever for agent reliability." },
  { d:"agent", lvl:3, q:"Which can be used as an agent action?", a:["Flows, Apex, prompt templates, and standard actions","Flows only","Validation rules","Assignment rules"], c:0, e:"Actions are how an agent does things. Reusing an existing autolaunched flow is usually the fastest path from an admin's perspective." },
  { d:"agent", lvl:3, q:"What does grounding an agent's response mean?", a:["Supplying trusted company data as context so the answer reflects real records","Limiting response length","Blocking toxic language","Logging the conversation"], c:0, e:"Dynamic grounding pulls in CRM data, Knowledge articles, or Data Cloud content at runtime, which is what keeps answers accurate rather than invented." },
  { d:"agent", lvl:3, q:"How do you check an agent's behavior before it goes live?", a:["Use the conversation preview in Agent Builder and the Testing Center","Deploy to production and monitor","Run a report","Check the Setup Audit Trail"], c:0, e:"The preview panel shows the reasoning: which topic was selected and which actions ran. Testing Center runs batches of test utterances to catch regressions." },
  { d:"agent", lvl:4, q:"Which scenario is a poor fit for a generative AI agent?", a:["Calculating an exact commission payout that must be auditable","Summarizing a long case history","Drafting a customer email","Answering policy questions from Knowledge"], c:0, e:"Deterministic, auditable math belongs in a flow or formula. Generative AI is for language, summarization, and judgment — not for guaranteeing arithmetic." },
  { d:"agent", lvl:4, q:"What's the difference between an Agentforce Service Agent and an Employee Agent?", a:["Service Agents face customers on external channels; Employee Agents help internal users inside Salesforce or Slack","Only Service Agents use the Trust Layer","Employee Agents can't call flows","There is no difference"], c:0, e:"The distinction matters for licensing, channel setup, and how tightly you scope permissions — customer-facing agents warrant a much narrower running-user profile." },
  { d:"agent", lvl:4, q:"In Prompt Builder, which template type would you use to generate a summary shown on a record page?", a:["Record summary","Sales email","Field generation","Flex"], c:0, e:"Record summary templates ground on a specific record's fields and related data. Flex templates are the general-purpose type for other contexts." },
  { d:"agent", lvl:2, q:"An agent keeps picking the wrong topic for a common request. What do you fix first?", a:["The topic's classification description","The agent's running user","The Data Cloud connection","The session timeout"], c:0, e:"The classification description is what the agent reads to decide which topic applies. Making it specific about scope, and about what it does not cover, resolves most misrouting." },
];

/* Batch 3 — written to fill thin domain/level cells. Appended, never inserted,
   so existing question ids stay stable for saved progress. */
const QUESTIONS3 = [
  /* sales */
  { d:"sales", lvl:1, q:"Which object records that a specific person was targeted by a specific campaign?", a:["Campaign Member","Campaign Influence","Lead","Contact Role"], c:0, e:"Campaign Member is the junction between a Campaign and a Lead or Contact, and it carries the per-campaign status like Sent, Responded, or Attended." },
  { d:"sales", lvl:1, q:"Which Opportunity field records the campaign that gets credit for the deal?", a:["Primary Campaign Source","Lead Source","Campaign Member Status","Type"], c:0, e:"Primary Campaign Source is a single lookup that populates automatically on lead conversion. Crediting several campaigns instead requires Campaign Influence." },
  { d:"sales", lvl:1, q:"What happens to a Lead record after it's converted?", a:["It becomes read-only and drops out of standard lead views","It's deleted permanently","It stays fully editable","It converts to a Case"], c:0, e:"The lead still exists and can be reported on with the Converted filter, but it can't be edited. Only users with the 'View and Edit Converted Leads' permission can reopen it." },
  { d:"sales", lvl:4, q:"Only the EMEA team should be able to use the EMEA price book. How do you control that?", a:["Share the price book, granting View access to an EMEA public group","Deactivate it for other users","Use a validation rule on Opportunity","Use field-level security on the price"], c:0, e:"Price books have their own sharing model with View and Use access levels, set from the price book's Sharing button. Access is independent of the Opportunity's sharing." },
  { d:"sales", lvl:4, q:"A discontinued product must stop appearing on new opportunities but stay on historical ones. What do you do?", a:["Uncheck Active on the product","Delete the product","Remove it from the standard price book only","Archive the price book"], c:0, e:"Deactivating hides it from new selections while preserving the line items on closed deals. Deleting would break historical reporting, and Salesforce blocks it once the product is in use." },

  /* service */
  { d:"service", lvl:1, q:"Which feature lets customers search articles and resolve issues without contacting an agent?", a:["A public Experience Cloud site with Knowledge","Case assignment rules","Omni-Channel","Macros"], c:0, e:"Knowledge articles published to a public site deflect cases. Article visibility there is still governed by data categories and channel settings." },
  { d:"service", lvl:4, q:"Customer replies to an Email-to-Case message are creating brand-new cases instead of attaching to the original. What's the likely cause?", a:["Email threading is broken, so replies can't be matched to the existing case","Assignment rules are inactive","The case was closed","Auto-response rules are misconfigured"], c:0, e:"Salesforce matches replies using a thread identifier. If the token was stripped from the template or threading settings changed, each reply looks like a new inbound email." },
  { d:"service", lvl:2, q:"An agent should see a case's related contact, account, and open cases in a single screen without clicking away. What do you configure?", a:["A console app with a customized record page and related lists","A report","A macro","A queue"], c:0, e:"Console apps combine the workspace layout, related-list components, and utility bar so agents keep context. This is the main reason support teams use console rather than standard apps." },

  /* productivity */
  { d:"prod", lvl:1, q:"What does @mentioning a colleague in a Chatter post do?", a:["Notifies them and links to their profile","Assigns them a task","Grants them record edit access","Adds them to the account team"], c:0, e:"Mentions notify and link, but they don't grant access. If the person can't see the underlying record, the post won't make it visible to them." },
  { d:"prod", lvl:3, q:"Support replies should come from support@company.com rather than each agent's personal address. What do you configure?", a:["An organization-wide email address","A letterhead","Email deliverability settings","A shared queue"], c:0, e:"Org-wide email addresses let chosen profiles send as a shared address. The address must be verified before it can be used." },
  { d:"prod", lvl:3, q:"Users report that a quick action they need is missing from a record in the mobile app but present on desktop. Where do you look?", a:["The Salesforce Mobile and Lightning Experience Actions section of the page layout","The compact layout","The global publisher layout","Field-level security"], c:0, e:"That section overrides the default action set once it's been customized. If it's never been edited, mobile inherits from the publisher actions instead." },
  { d:"prod", lvl:4, q:"Which Classic email template type requires a letterhead?", a:["HTML (using Letterhead)","Text","Custom (without using Letterhead)","Visualforce"], c:0, e:"Letterheads define the branded header, footer, and colors, and only the HTML-using-Letterhead type consumes one. Lightning email templates don't use letterheads at all." },
  { d:"prod", lvl:4, q:"A user needs to log a call against an opportunity and have it visible on the related account too. What makes that happen automatically?", a:["Activity rollup from the opportunity to its parent account","Shared Activities","Feed tracking","A validation rule"], c:0, e:"Activities logged against an opportunity, contact, or case roll up to the related account's activity timeline, which is why account owners see team activity without extra configuration." },

  /* agentforce */
  { d:"agent", lvl:1, q:"Where do you configure an agent's topics, instructions, and actions?", a:["Agent Builder","Flow Builder","Prompt Builder","Lightning App Builder"], c:0, e:"Agent Builder is the home for agent configuration. Prompt Builder is a separate tool for authoring the prompt templates that agents can call as actions." },
  { d:"agent", lvl:1, q:"In one sentence, what is Agentforce?", a:["A platform for building AI agents that reason over trusted CRM data and take action","A reporting tool","A data migration tool","A replacement for Flow"], c:0, e:"The distinguishing feature is that agents act, not just answer — they invoke real actions like flows and Apex, under the permissions of the user they run as." },
  { d:"agent", lvl:3, q:"An agent must report the shipping status of an order held in an external ERP. What's the admin approach?", a:["Build an action that retrieves the data, and assign it to the relevant topic","Paste the data into the instructions","Ask the model to infer it","Enable Data Cloud only"], c:0, e:"Agents can only use data they retrieve. An action backed by a flow, an External Service, or Data Cloud fetches live values instead of the model guessing." },
  { d:"agent", lvl:3, q:"Where do you review what an agent actually said to customers after deployment?", a:["Agent conversation transcripts and the Trust Layer audit trail","Setup Audit Trail","Field history tracking","Debug logs"], c:0, e:"The audit trail captures prompts, responses, and Trust Layer interventions like masking and toxicity scoring, which is what makes agent behavior reviewable." },
  { d:"agent", lvl:4, q:"A service agent should hand a conversation to a human when the customer becomes frustrated. How do you build that?", a:["Write an instruction defining the handoff condition, plus an escalation action that routes to a queue","Lower the agent's permissions","Disable the topic","Shorten the response length"], c:0, e:"Handoff is two parts: the instruction tells the agent when, and the action does it, typically routing through Omni-Channel to a live agent queue." },
];


export const ALLQ = [...QUESTIONS, ...QUESTIONS2, ...QUESTIONS3].map((q, i) => ({ ...q, id: i }));
